   "role": "skill",
   "section": "Purpose and authority",
   "line_start": 42,
   "line_end": 45,
   "stage": "gate",
   "text": "Declared incentives and conditional solver output inform inquiry, never replace human perspective accounts or satisfy this release gate.",
